#!/usr/bin/env python3
"""Build a public static evaluation view from an admitted private report; stdlib only."""
import argparse,hashlib,html,json,re
from pathlib import Path

def need(ok,msg):
    if not ok: raise ValueError(msg)
def selected(obj,keys):return {k:obj[k] for k in keys}
def scan_public(value):
    text=json.dumps(value,ensure_ascii=False)
    forbidden=[r'/(?:Users|home|root|workspace|var|proc|tmp|opt)/',r'file://',r'localhost',r'\b(?:\d{1,3}\.){3}\d{1,3}\b',r'\bses_[a-zA-Z0-9]+',r'\bcall_[a-zA-Z0-9]+',r'Bearer\s+\S+',r'-----BEGIN .*PRIVATE KEY',r'\bgh[pousr]_[A-Za-z0-9_]+',r'\b(?:sk-proj|sk-ant)-[A-Za-z0-9_-]+']
    need(not any(re.search(pattern,text,re.I) for pattern in forbidden),'public view contains disallowed private material')

def project(report,portable,package,version):
    need(report['assessmentAuthority']['reportProducer']=='evaluation_system' and report['assessmentAuthority']['studentSelfGradeAuthoritative'] is False,'not independent system assessment')
    need(report['caseCount']==1 and len(report['cases'])==1,'select one case for this report')
    c=report['cases'][0];target=json.loads(c['target']) if isinstance(c['target'],str) else c['target'];need(re.fullmatch(r'[\w.-]+/[\w.-]+',target['repository']) is not None,'invalid public target')
    t=report['toolActivitySummary'];need(0<=t['coveredOperations']<=t['totalOperations']==report['operationCount'],'invalid coverage');need(t['returnedWithoutError']+t['returnedWithError']+t['unknownResultCalls']==t['identifiedCalls'],'invalid call totals')
    need(sum(report['outcomeCounts'].values())==report['operationCount'],'invalid operation totals');a=c['reviewedLearning'];h=c['reportAnalysis']['helpClassification'];need(a['reviewedCalls']<=t['identifiedCalls'],'invalid reviewed coverage')
    rows=[]
    for i,o in enumerate(c['operations'],1):
        need(o['durationMs']>=0,'invalid duration');rows.append({'sequence':i,**selected(o,['phase','model','runtimeStatus','outcome','durationMs','finding'])})
    data={'schema':'agentlab.public-evaluation.v1','version':version,'evidenceDate':'2026-10-25','caseTitle':'Calendar：代码开发、设备验证与长程交付','target':selected(target,['repository','commit','scope']),'assessmentAuthority':'评测系统与教师独立审阅，学生交付物不作为最终成绩','scope':'单个提取的ArkUI验收应用，来自目标库；受辅助的长程任务，不代表整个Calendar项目或模型总体能力','wholeIndependentTaskPass':False,'score':None,'scorePolicy':'事实与评分权重分离；尚未设定总分，不作模型排名','metrics':{'caseCount':1,'operationCount':report['operationCount'],'helpContextEvents':report['teacherHelpCount'],'studentDurationMs':report['studentDurationMs'],'uiEvidenceChecksPassed':portable['UIEvidenceChecks'],'uiEvidenceChecksTotal':7},'tools':selected(t,['identifiedCalls','coveredOperations','totalOperations','unavailableOperations','returnedWithoutError','returnedWithError','unknownResultCalls']),'outcomeCounts':report['outcomeCounts'],'dimensions':[selected(x,['id','name','status','finding']) for x in c['dimensions']],'capabilityClaims':[selected(x,['title','finding','confidence','alternativeExplanations']) for x in a['capabilityClaims']],'assistanceComparisons':[selected(x,['title','beforeFinding','helpFinding','afterFinding','confounders','causalEffectEstablished']) for x in a['assistanceComparisons']],'reviewCoverage':{'reviewedCalls':a['reviewedCalls'],'identifiedCalls':a['identifiedCalls'],'globalUsefulCallFraction':None},'helpClassification':selected(h,['eventCount','typedEvents','unclassifiedEvents','tagAssignments']),'operations':rows,'portable':{'hosts':['macOS','Linux'],'sameArchiveVerified':portable['macLinuxExactRegradeEqual'],'reportJSONEqual':True,'reportHTMLEqual':True,'retainedPoints':package['pointCount'],'archiveBytes':package['archiveBytes'],'latestPatchBytes':package['patchBytes'],'sharedBaseBytes':package['baseBundleBytes'],'selectedFiles':package['selectedSnapshotFiles'],'selectedBytes':package['selectedBytes'],'privateEvidenceLogicalBytes':package['privateEvidenceLogicalBytes'],'newStudentOrDeviceActions':0,'scope':'选定源码与证据的恢复、历史UI证据判断和报告离线重算；第二台机器未重新编译、操作设备或继续学生Agent。SDK、构建缓存和整个Capsule未恢复。旧图片预览未纳入本次重算视图，原始材料单独保留。'},'cost':{'billing':None,'performanceThisExtension':'未新增性能测量；构建耗时、模型运行时长和应用性能分开记录'},'provenance':{'privateReportSHA256':hashlib.sha256(json.dumps(report,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'reviewPolicy':a['policyVersion'],'publicProjectionPolicy':'allowlist-v1','privateArtifactsPublished':False},'limitations':['31轮是同一用例的历史执行操作，不是31道独立题。','7/7是跨受辅助续跑得到的UI历史证据检查，不是整题独立通过率。','8次关键调用为定向审阅，不能外推全程有效调用率。','帮助后的进展伴随额外预算、已有产物和上下文变化，不能作单一因果归因。','历史配置文字标签尚未按完整实测配置归一，不能据此排名模型。','私有原始轨迹、评测器、任务包、服务地址和登录信息不在公开站点。']}
    need(data['metrics']['uiEvidenceChecksPassed']==data['metrics']['uiEvidenceChecksTotal'],'unexpected UI summary');need(len(data['dimensions'])==8,'expected eight assessment dimensions');scan_public(data);return data

CSS='''*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#18253d;font:16px/1.7 system-ui,-apple-system,sans-serif}main{max-width:1120px;margin:auto;padding:30px 24px 64px}nav{display:flex;justify-content:space-between;gap:16px;font-weight:650}a{color:#235fc4;text-decoration:none}a:hover{text-decoration:underline}.eyebrow{color:#526780;margin:32px 0 8px}h1{font-size:clamp(28px,4vw,44px);line-height:1.3;margin:10px 0 20px}h2{margin:40px 0 15px;font-size:25px}h3{font-size:19px}p{max-width:90ch}.lede{font-size:18px;color:#42546f}.cards,.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.card,.panel{background:white;border:1px solid #dce3ef;border-radius:14px;padding:22px}.card strong{display:block;font-size:30px;color:#1d4b86}.card span{font-size:14px;color:#50617a}.badge{display:inline-block;background:#e8eef8;border-radius:20px;padding:4px 12px;font-size:13px}.notice{border-left:4px solid #ca9541;background:#fff8ea;padding:15px 20px}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.grid p{font-size:15px}.muted,small{color:#5c6c83}details{background:#fff;border:1px solid #dce3ef;border-radius:10px;padding:16px 20px;margin:12px 0}summary{cursor:pointer;font-weight:650}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #e0e5ed}th{white-space:nowrap}code{font-size:12px;overflow-wrap:anywhere}.bar{height:10px;background:#e5ebf4;border-radius:5px;overflow:hidden}.bar b{display:block;background:#43809a;height:100%}footer{margin-top:40px;border-top:1px solid #dae2ee;padding-top:20px;font-size:13px}.links{display:flex;gap:20px;flex-wrap:wrap}li{margin:7px 0}section{scroll-margin-top:20px}@media(max-width:700px){main{padding:22px 16px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}.card{padding:16px}nav{font-size:14px}td{min-width:100px}}'''
def page(data):
    e=lambda x:html.escape(str(x));m=data['metrics'];t=data['tools'];a=data['reviewCoverage'];h=data['helpClassification'];p=data['portable'];labels={'independent_qualified':'阶段独立合格','assisted_qualified':'帮助后阶段合格','failed':'失败保留','partial':'部分验证','completed_ungraded':'完成／未判分'}
    cards=''.join('<div class="card"><strong>'+e(n)+'</strong><span>'+e(label)+'</span></div>' for n,label in [(str(m['uiEvidenceChecksPassed'])+'/7','受辅助续跑的UI证据检查'),(m['operationCount'],'历史执行轮次，非独立用例数'),(m['helpContextEvents'],'帮助与上下文事件'),(str(t['coveredOperations'])+'/'+str(t['totalOperations']),'工具明细覆盖的执行轮次')])
    claims=''.join('<article class="panel"><h3>'+e(x['title'])+'</h3><p>'+e(x['finding'])+'</p><small>'+e('；'.join(x['alternativeExplanations']))+'</small></article>' for x in data['capabilityClaims'])
    dims=''.join('<details><summary>'+e(x['name'])+'</summary><p>'+e(x['finding'])+'</p></details>' for x in data['dimensions'])
    pairs=''.join('<article class="panel"><h3>'+e(x['title'])+'</h3><div class="grid">'+''.join('<div><b>'+label+'</b><p>'+e(x[key])+'</p></div>' for label,key in [('帮助前','beforeFinding'),('实际帮助','helpFinding'),('帮助后','afterFinding')])+'</div><p class="muted">其他变化：'+e('；'.join(x['confounders']))+'。不作单一因果归因。</p></article>' for x in data['assistanceComparisons'])
    rows=''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in [o['sequence'],o['phase'],o['model'],o['runtimeStatus'],labels[o['outcome']],f"{o['durationMs']/1000:.3f}",o['finding']])+'</tr>' for o in data['operations'])
    portability=''.join('<tr><td>'+label+'</td><td>'+e(value)+'</td></tr>' for label,value in [('复核环境','macOS 与 Linux'),('保留历史点',p['retainedPoints']),('私有任务包',f"{p['archiveBytes']/1000000:.2f} MB"),('最新差异补丁',f"{p['latestPatchBytes']/1000:.1f} KB"),('共享Git基线',f"{p['sharedBaseBytes']/1000:.1f} KB"),('选定源码／证据',str(p['selectedFiles'])+' 个文件'),('两机生成的结构化判断与网页','完全一致')])
    body=f'''<nav><a href="../../../">AgentLab · 评测报告</a><a href="https://github.com/yxsicd/agentlabrelease">GitHub</a></nav><p class="eyebrow">公开评测视图 · {e(data['evidenceDate'])} · 单任务探索样板</p><h1>{e(data['caseTitle'])}</h1><p class="lede">局部自主纠错已有证据；完整任务的独立完成尚未证明。评测围绕同一任务逐步加深，教师帮助与早期失败持续计入。</p><div class="cards">{cards}</div><p class="notice">{e(data['scope'])}。{e(data['scorePolicy'])}。</p><p class="links"><a href="#capabilities">能力与难点</a><a href="#help">帮助归因</a><a href="#portability">迁移复核</a><a href="#history">历史执行</a><a href="evaluation.json">公开结构化数据</a></p><section id="capabilities"><h2>从已有行为能判断什么</h2><p>关键调用已审阅 {a['reviewedCalls']}/{a['identifiedCalls']} 次。这是定向选取的事件，尚不能计算总体有效调用率。</p><div class="grid">{claims}</div><h2>八维能力观察</h2>{dims}</section><section id="help"><h2>帮助使任务走到了哪里</h2><p>{h['eventCount']} 个帮助／上下文事件中，{h['typedEvents']} 个有明确类型，{h['unclassifiedEvents']} 个待复核。一件事可能有多个类型，不能按标签数重复计分；上下文说明与解法提示也不能等量扣分。</p>{pairs}</section><section><h2>工具返回与任务进展分开看</h2><p>明细覆盖 {t['coveredOperations']}/{t['totalOperations']} 轮（{100*t['coveredOperations']/t['totalOperations']:.1f}%），其余 {t['unavailableOperations']} 轮未提取工具明细，不能记成零调用。</p><div class="bar"><b style="width:{100*t['coveredOperations']/t['totalOperations']:.1f}%"></b></div><p>已识别 {t['identifiedCalls']} 次调用：未显式报错 {t['returnedWithoutError']} 次、显式报错 {t['returnedWithError']} 次、结果未知 {t['unknownResultCalls']} 次。正常返回仍可能包含操作错误；失败也可能提供有效信息。</p></section><section id="portability"><h2>同一任务包的跨机复核</h2><div class="panel"><table>{portability}</table><p>{e(p['scope'])}</p><p>私有任务包和原始证据继续单独保留，公开页不提供下载。</p></div></section><section id="history"><h2>历史执行与原始失败</h2><p>不同轮次的预算、上下文、帮助和历史配置标签不同；阶段合格不代表整题独立通过。</p><details><summary>展开 {m['operationCount']} 轮执行摘要</summary><div class="scroll"><table><thead><tr><th>轮次</th><th>阶段</th><th>历史配置标签</th><th>原生状态</th><th>阶段评价</th><th>秒</th><th>观察与边界</th></tr></thead><tbody>{rows}</tbody></table></div></details></section><section><h2>范围、未知项与依据</h2><ul>{''.join('<li>'+e(x)+'</li>' for x in data['limitations'])}</ul><p>费用未核实，当前扩展未新增性能测量。来源：<a href="https://github.com/{e(data['target']['repository'])}/tree/{e(data['target']['commit'])}">{e(data['target']['repository'])}</a> 的提取验收应用。</p><details><summary>评测版本与证据承诺</summary><p>{e(data['assessmentAuthority'])}</p><p>分析策略：{e(data['provenance']['reviewPolicy'])}；公开导出策略：{e(data['provenance']['publicProjectionPolicy'])}</p><p>私有评测输入的内容摘要：<code>{e(data['provenance']['privateReportSHA256'])}</code>。该摘要用于后续授权核验，不提供私有原文。</p></details></section><footer>AgentLab · 公开报告，不是学生自评。版本 {e(data['version'])}。无外部脚本、跟踪器或后端依赖。</footer>'''
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="AgentLab 单任务长程评测：能力、帮助归因、执行证据与迁移复核"><title>Calendar 长程任务评测 · AgentLab</title><style>'+CSS+'</style><main>'+body+'</main></html>'

def build(source,portable_path,package_path,output,version):
    need(re.fullmatch(r'[a-z0-9-]+',version) is not None,'invalid version');need(not output.exists(),'output exists; keep published versions immutable')
    data=project(json.loads(source.read_text()),json.loads(portable_path.read_text()),json.loads(package_path.read_text()),version);rendered=page(data);scan_public(rendered)
    output.mkdir(parents=True);(output/'evaluation.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');(output/'index.html').write_text(rendered);return {'publicFiles':2,'sourceCommitment':data['provenance']['privateReportSHA256'],'htmlBytes':len(rendered.encode()),'jsonBytes':(output/'evaluation.json').stat().st_size}

def main():
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--portable-validation',type=Path,required=True);p.add_argument('--package-digest',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--version',required=True);a=p.parse_args();print(json.dumps(build(a.source,a.portable_validation,a.package_digest,a.output,a.version)))
if __name__=='__main__':main()
